namespace CodeGenNew.Core;

/// <summary> One line of meaning for each project setting key: what it does and what a blank value means. The Project Settings screen shows it beside the box, and a test keeps
/// it and Docs/Reference.md complete as keys are added. </summary>
public static class ProjectSettingsHints
{
    /// <summary> The settings that are true or false: the settings screen shows a check box for each. </summary>
    public static IReadOnlySet<string> BooleanKeys { get; } = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        "ApiDocs", "ApiHttp", "ApiFakers", "ProjectDocs", "ApiValidation", "ApiCsv", "OData", "EfConfigurations", "ApiProduction", "ApiTelemetry", "ApiTests", "ApiTestContainers", "BlazorTests", "DesktopTests", "RustTests", "PythonTests", "ApiAuth", "Dtos", "Dashboard", "DashboardStrip", "Auth"
    };

    /// <summary> The caption of a setting with the words apart: "DashboardStrip" -> "Dashboard Strip". </summary>
    public static string Caption(string key) => ScreenNames.Words(key);

    public static IReadOnlyDictionary<string, string> All { get; } = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
    {
        ["ViewNamespace"] = "blank = <ProjectName>.App.Views",
        ["ViewModelNamespace"] = "blank = <ProjectName>.App.ViewModels",
        ["ContextName"] = "blank = <ProjectName>Context",
        ["ContextNamespace"] = "blank = <ProjectName>.App.Data",
        ["ApiNamespace"] = "blank = <ProjectName>.ApiService.Apis",
        ["EnumNamespace"] = "blank = <ProjectName>.App.Enums",
        ["RepoNamespace"] = "blank = <ProjectName>.App.Repositories",
        ["EntityNamespace"] = "blank = <ProjectName>.App.Entities",
        ["MinYear"] = $"blank = {ProjectSettings.DefaultMinYear}",
        ["MaxYear"] = $"blank = {ProjectSettings.DefaultMaxYear}",
        ["CurrencyCode"] = "ISO currency code for money fields; blank = USD",
        ["MaxGridColumns"] = $"the most columns a generated grid shows (long text is never shown); blank = {GridColumns.DefaultMaxColumns}",
        ["ViewsFolder"] = "blank = the template's own folder",
        ["ViewModelsFolder"] = "blank = the template's own folder",
        ["Usings"] = "comma-separated namespaces every generated file should use",
        ["DetailMasterTables"] = "comma-separated table names whose Add/Edit dialog is a Detail-Master dialog (with child grids)",
        ["HiddenParents"] = "comma-separated tables whose foreign key columns the TypeScript forms hide",
        ["ModelFileOverrides"] = "Table=file pairs for model files not named after the table, e.g. DepartmentTeam=department,ProjectTask=project",
        ["BaseEntity"] = "base class of generated entities; blank = BaseEntity",
        ["BaseNameActiveEntity"] = "base class for Name + IsActive tables; blank = BaseNameActiveEntity",
        ["EnumTables"] = "comma-separated enum tables (no entity, repository or API); blank = decided from each table's shape",
        ["EnumNameSuffixes"] = "comma-separated name endings that mark an enum table; blank = Type, Types, Code, Codes, Status, Kind",
        ["EnumMaxRows"] = $"a lookup table with more rows than this is not an enum; blank = {ProjectSettings.DefaultEnumMaxRows}",
        ["TypeAheadRows"] = $"a parent with more rows than this is picked by typing (a type-ahead that asks the API for matches) instead of a drop-down of every row; 0 = never; blank = {ProjectSettings.DefaultTypeAheadRows}",
        ["TypeAheadParents"] = "tables that are always picked by typing, whatever their row count",
        ["NoLookupParents"] ="overrides EnumTables for this one question: tables whose foreign key is a number box, not a drop-down",
        ["NoRepositoryTables"] = "overrides EnumTables for this one question: tables that get no repository",
        ["NoApiTables"] = "overrides EnumTables for this one question: tables that get no API or TypeScript model/screen",
        ["NoNavigationTables"] = "overrides EnumTables for this one question: tables referenced without a navigation property",
        ["FakerNamespace"] = "the namespace of the Bogus fakers CS_Faker writes (default <ProjectName>.App.Fakers)",
        ["ApiDocs"] = "The plan also writes openapi.yaml (API_OpenApi) and the API serves it with a Swagger UI page at /docs.",
        ["ApiFakers"] = "The plan also writes a Bogus fake-data generator per table (CS_Faker) and the generated project references Bogus.",
        ["ApiProduction"] = "The API project also gets a production profile (Problem Details, health checks at /health/live and /health/ready, rate limiting, response compression, security headers) and a Dockerfile. Nothing beyond ASP.NET Core is referenced.",
        ["ApiTelemetry"] = "The API project also gets OpenTelemetry traces, metrics and logs (Telemetry.cs) and references the OpenTelemetry packages. Nothing is sent until OTEL_EXPORTER_OTLP_ENDPOINT names a collector (environment variable or appsettings.json).",
        ["BlazorTests"] = "The plan also writes a bUnit test class per Blazor page (BLZ_Test) and a test project (MSTest and bUnit) beside the Blazor app: the page shows a row the server returns, Edit opens the dialog, Save sends the row, and ?edit=<key> opens a row. The API is a stand-in, so no database is needed.",
        ["DesktopTests"] = "The plan also writes a test class per WinUI 3 and Uno dialog and a test project (MSTest) beside each app: the real view model refuses a new row with nothing filled in, saves a row it opened with every value it had, and refuses each rule of the form (a shape, a date later than today, an end before its start, a number that is not whole). WinUI 3 runs over an in-memory SQLite database made from the generated context, Uno over a stand-in for the API; no window and no server are needed. Regenerate the WinUI3 or Uno stack.",
        ["PythonTests"] = "The plan also writes pytest tests into the Python API (tests/conftest.py and tests/test_approvals.py, for a project with RowApprovals and ApiAuth): the approval routes through the application in process, over a copy of the SQLite file or, for PostgreSQL and MySQL, the scratch database in <PROJECT>_TEST_CONNECTION. The people and the row are added with SQL and removed again. requirements.txt then lists pytest and httpx. Run pytest from the API's folder",
        ["RustTests"] = "The plan also writes integration tests into the Rust crate (tests/api): a file per table, per junction table, and for the dashboard, the CSV routes and the gates when the project has them, with the helper they share. They run the router in process, so `cargo test` needs no server. SQLite tests run over a copy of the database file; PostgreSQL and MySQL need <PROJECT>_TEST_CONNECTION (a URL of a scratch copy), or a test says why it did nothing and passes.",
        ["ApiTestContainers"] = "With ApiTests and a PostgreSQL, MySQL or SQL Server database, the test project starts a throwaway container of that database (Testcontainers; Docker must be running) when <ProjectName>_TEST_CONNECTION is not set, fills it from ApiTestSchema and tests over it. SQLite needs no container.",
        ["ApiTestSchema"] = "comma-separated SQL scripts a test container is filled from, relative to the API project's folder, applied in the order listed (a folder means every .sql file in it by name): the create script of the database, then the routines the plan wrote when AccessMode is not Ef",
        ["ApiTests"] = "The plan also writes an integration test class per table (API_Test) and a test project (MSTest and Microsoft.AspNetCore.Mvc.Testing) beside the API. SQLite tests run over a copy of the database file; other databases need <ProjectName>_TEST_CONNECTION (a scratch copy) or the tests report themselves as inconclusive.",
        ["ApiAuth"] = "The API signs people in: JWT bearer wiring, POST /api/auth/login, and every other endpoint needs a token (the Jwt essentials group; the package Microsoft.AspNetCore.Authentication.JwtBearer). The signing key comes from Jwt:Key (an environment variable, never a file) and the first administrator from Bootstrap:AdminUserName and Bootstrap:AdminPassword; register your own IUserDirectory for real users. Regenerate the project and refresh the CrudApi and Program groups with --replace.",
        ["OwnedTables"] = "With ApiAuth: comma-separated tables whose rows belong to a person (TimeSheet,Expense); Table:Column names another owner column (DonateLeave:DonateFrom_EmployeeId). A caller reads and writes only the rows of the owners the IOwnerScope allows (their own, or everyone's for the administrator role); blank = no table is scoped",
        ["OwnerColumn"] = "With OwnedTables: the NOT NULL whole-number column that holds a row's owner; blank = EmployeeId",
        ["RequiredMarks"] = "A red * after the caption of every required field on the generated forms (all stacks); false = no marks; blank = true. Regenerate the screens to apply it",
        ["OwnedChildren"] = "With OwnedTables: a table with a NOT NULL foreign key to an owned table belongs to the owner of that parent row (time-sheet detail rows); false = such tables are not scoped; blank = true",
        ["AuthRoleClaim"] = "With ApiAuth: the name of the token claim that carries the person's role; blank = role",
        ["AuthOwnerClaim"] = "With ApiAuth: the name of the token claim that carries the owner id (the person's employee id); blank = employeeId",
        ["AuthAdminRole"] = "With ApiAuth: the role that sees and changes every row of an owned table; blank = Administrator",
        ["UserTable"] = "With ApiAuth: the table whose rows are the people who sign in (Employee); the API checks the password against its hash column and fills the token's role and owner id from it. Blank = only the bootstrap administrator. Needs the four column settings below; regenerate the project and refresh the Program group with --replace",
        ["UserNameColumn"] = "With UserTable: the text column that holds the sign-in name (Login); it should be unique. Rows where it is empty cannot sign in. Blank = the one column called Login, LoginName, UserName or the like",
        ["PasswordHashColumn"] = "With UserTable: the text column that holds the password hash, at least 90 characters wide (varchar(200)); blank = the one column called PasswordHash, Pword or the like. Never a password: set one with `dotnet run -- set-password <name>` and the environment variable NEW_PASSWORD",
        ["UserOwnerColumn"] = "With UserTable: the whole-number column that goes into the token as the owner id (EmployeeId); blank = no owner id",
        ["UserRoleColumn"] = "With UserTable: a yes/no column (IsManager: the role is the two names below) or a text column that holds the role's name; blank = no role",
        ["UserAdminColumn"] = "With UserTable: a yes/no column (IsAdministrator); true makes the person an administrator (the AuthAdminRole, which sees every owner's rows), whatever UserRoleColumn says; blank = the one yes/no column called IsAdministrator, IsAdmin or the like, and nobody is an administrator when there is none",
        ["UserRoleWhenTrue"] = "With a yes/no UserRoleColumn: the role of a row where it is true; blank = Manager",
        ["UserRoleWhenFalse"] = "With a yes/no UserRoleColumn: the role of a row where it is false; blank = Employee",
        ["ChangeGates"] = "With ApiAuth: rules that hold a change, one per table column, separated by |: Table.Column; to 2,3 (or to > 1); when Parent.Column=2 (and / or allowed); unless Parent.Column=1; start 1 (a new row always starts as this); message \"words\". The API answers 409 change-not-allowed. Blank = none. Regenerate the API; the screens show the server's words",
        ["ReadRoles"] = "With ApiAuth: the roles that may read rows (Administrator,Hr); the administrator role always may. Blank = any signed-in person. The drop-down lookup of a table stays open to every signed-in person. Regenerate the API and the screens",
        ["TableReadRoles"] = "With ApiAuth: the read roles of single tables, separated by ; (Salary:Administrator,Hr), instead of ReadRoles; Table: alone lets any signed-in person read it. Blank = ReadRoles for every table",
        ["WriteRoles"] = "With ApiAuth: the roles that may create, change and delete rows (Administrator,Manager); the administrator role always may. Blank = any signed-in person. Reading stays open. Regenerate the API and the screens",
        ["TableWriteRoles"] = "With ApiAuth: the write roles of single tables, separated by ; (Holiday:Administrator;LeaveType:Administrator,Manager), instead of WriteRoles; Table: alone lets any signed-in person write it. Blank = WriteRoles for every table",
        ["LogTables"] = "comma-separated insert-only tables the application only reads (ErrorLog, UserSession:StartedOn, a table and optionally its timestamp column): no write routes, a list that opens newest first with a date range and no Add, Edit, Clone or Delete; needs AccessMode=Ef; regenerate the API and every front end",
        ["QueueTables"] = "comma-separated work-queue tables (JobQueue, Mail:State:Attempts, a table and optionally its status and retry columns): claim, complete, fail and retry routes, a read-only list with the counts by status and a Retry button on failed rows; needs a pending, claimed, done and failed status, a created, claimed and processed stamp; needs AccessMode=Ef; regenerate the API and the web front ends",
        ["QueueMaxRetries"] = $"How many times a queue row may fail before it stays failed; blank = {ProjectSettings.DefaultQueueMaxRetries}",
        ["QueueClaimMinutes"] = $"The minutes after which a claim nobody completed goes back to pending; blank = {ProjectSettings.DefaultQueueClaimMinutes}",
        ["ArchiveTables"] = "comma-separated tables whose old rows a script moves to <Table>Archive (ErrorLog:90, JobQueue:30:delete: the days to keep, then delete to remove the rows instead); the SP_ArchiveJob script is written for you to review and schedule, the application never runs it; an archive table the database has is shown as a read-only list",
        ["ArchiveBatchSize"] = $"The rows one batch of the archive script moves or deletes; blank = {ProjectSettings.DefaultArchiveBatchSize}",
        ["ArchiveRunAt"] = $"The time of day (HH:mm, 24 hours) the commented scheduling text of the archive script runs it at; blank = {ProjectSettings.DefaultArchiveRunAt}",
        ["TreeTables"] = "comma-separated self-referencing tables (Category, Comment:ParentId:4: a table, optionally its parent column and the deepest level): a parent that is the row itself or one of its descendants is refused, a row with children is not deleted (POST {id}/promote-children first hands them up), and GET tree answers the rows depth first; needs AccessMode=Ef and the ASP.NET API; regenerate the API and refresh the CrudApi essentials",
        ["SoftDeleteTables"] = "comma-separated tables whose rows are flagged instead of removed (Customer, Order:IsRemoved: the yes/no column, default IsDeleted; DeletedOn and DeletedBy are filled when the table has them): the delete route sets the flag, the context hides flagged rows from every list and look-up, GET deleted lists them and POST {id}/restore brings one back; needs AccessMode=Ef and the ASP.NET API; regenerate the API and the context and refresh the CrudApi essentials",
        ["EffectiveDatedTables"] = "comma-separated tables whose rows are valid for a period (Price:ValidFrom:ValidTo:ItemId+CurrencyId: the first and last day, then the columns that say what the row is a price of, default every single-column foreign key; an empty last day is open): a save that runs backwards or overlaps another row of the group is refused, and GET current?on=2026-10-27 answers the rows in effect; needs AccessMode=Ef and the ASP.NET API; regenerate the API and refresh the CrudApi essentials",
        ["TenantTable"] = "With ApiAuth and AccessMode=Ef: the table of tenants (Tenant). Every other table with a NOT NULL whole-number column TenantId (TenantColumn) that is a foreign key to it is tenant-owned: the context filters every read by the tenant in the caller's token, the API fills the column on create and keeps it on update, and the tenant table shows only the caller's own tenant. ASP.NET API; regenerate the API and the context and refresh the CrudApi and Jwt essentials",
        ["TenantColumn"] = $"The column that holds a row's tenant in a tenant-owned table; blank = {TenantPlan.DefaultColumn}",
        ["NoTenantTables"] = "comma-separated tables that have the tenant column but are shared by every tenant (Country, Currency): no filter and no stamp",
        ["TenantMembership"] = "the junction that lets one person work in several tenants (UserTenant:UserId:TenantId:Role: the table, its person column, its tenant column and optionally a text role column; needs UserTable). The sign-in picks the first tenant, or the one asked for; GET /api/auth/tenants lists them and POST /api/auth/switch-tenant changes the token",
        ["ApproverTable"] = "With RowApprovals: who may approve is a table of rows (Approver:EmployeeId,TableName) instead of the user table's role flag. First the table, then the column holding the person (the user table's key), then optionally a text column naming the RowApprovals table the person may decide (blank there = every table). An administrator always may. Restrict who writes this table with TableWriteRoles. Regenerate the API; blank = the role flag decides",
        ["RowApprovals"] ="With ApiAuth and UserTable (UserRoleColumn a yes/no column): comma-separated tables whose rows each need a decision (TimeSheet,Expense). Each needs a <Table>Approval side table (the SP_ApprovalTable script creates it), one row per request cycle. The API gets request, approve, reject and withdraw routes, GET toapprove and a gate clause: approval; every front end gets an Approvals page. Regenerate the API; blank = none",
        ["GuardedColumns"] ="With ApiAuth and UserTable: columns only some people may change, separated by |: Table.Column; by Employee.IsManager (a yes/no column of the user table; administrators may too); stampBy Column; stampOn Column (set to the person and the time). Anyone else may save the row if the value is unchanged. Blank = none. Regenerate the API and the screens",
        ["OutputBlazorTests"] ="folder of the Blazor test project under the output folder; blank = <ProjectName>.Blazor.Tests",
        ["OutputWinUI3Tests"] = "folder of the WinUI 3 view-model test project under the output folder; blank = <ProjectName>.WinUI3.Tests",
        ["OutputUnoTests"] = "folder of the Uno view-model test project under the output folder; blank = <ProjectName>.Uno.Tests",
        ["OutputApiTests"] ="folder of the API test project under the output folder; blank = <ProjectName>.Api.Tests",
        ["ApiHttp"] = "The plan also writes a .http request file per table (API_Http).",
        ["ProjectDocs"] = "The plan also writes a data dictionary page per table and the ER diagram (MD_DataDictionary, MD_Erd).",
        ["ApiValidation"] = "The plan also writes a FluentValidation validator per table (CS_Validator) and the create and update endpoints run them (400 with the messages).",
        ["ApiCsv"] = "The plan also writes CSV export and import endpoints for every table (API_Csv) and Program.cs maps them: GET /api/<table>/export.csv and POST /api/<table>/import. Regenerate after ticking.",
        ["OData"] = "The API also serves the selected tables as OData v4 under /odata, next to the REST routes (which stay). The generated API project needs the Microsoft.AspNetCore.OData package. With ApiAuth the routes scope owned tables to the caller and run the change gates and guards, as the REST routes do; the user table, DTO projects and tables with editable child lists are refused with a reason in the generated file. Regenerate after ticking.",
        ["ODataTables"] = "The tables served as OData, separated by commas; blank or * = every table that has a CRUD API and is not refused.",
        ["ODataMaxTop"] = $"The most rows one OData request may ask for with $top; blank = {ProjectSettings.DefaultODataMaxTop}",
        ["ODataPageSize"] = $"The rows of one OData page; a longer answer carries a next link; blank = {ProjectSettings.DefaultODataPageSize}",
        ["ODataScreens"] = "With OData (Angular, React and Blazor): Add puts the OData screen of a served table after the REST screens as a second menu entry; Replace puts it in the REST screen's place (same route and text). A table hosted with dashboard cards keeps its REST screen. Blank = Add. Regenerate the Angular, React or Blazor screens",
        ["ODataExpandDepth"] = $"How many levels deep $expand may go; blank = {ProjectSettings.DefaultODataExpandDepth}",
        ["Dtos"] = "A table's CRUD API takes an input type (<Table>Input: only the columns a caller may set, not the identity key, computed or audit columns) and answers a transfer class (<Table>Dto: every column, no navigation). The plan also writes CS_Dto, CS_DtoInput and CS_Mapper; needs the Api stack. Regenerate after ticking.",
        ["EfConfigurations"] = "The plan also writes an IEntityTypeConfiguration per table (CS_EfConfiguration) and the context applies them from the assembly; composite keys move into them. Regenerate after ticking.",
        ["Dashboard"] = "The plan also writes the dashboard: its queries (CS_Dashboard, SP_Dashboard), the GET /api/dashboard endpoint (API_Dashboard), a page and menu entry per front end (TSX_Dashboard, TS_Dashboard, WinUI3_DashboardPage, BLZ_Dashboard, RS_Dashboard, PY_Dashboard) and a Markdown page listing the widgets (MD_Dashboard). On unless set to false. Regenerate the project after changing it.",
        ["DashboardStrip"] = "Needs Dashboard. Each table screen shows that table's two or three cards above its grid.",
        ["DashboardMeasures"] = "comma-separated widgets you name: Table.Column:sum|avg|max|min|count, or Table.Column:aggregate:DateColumn:day|month|year for a trend (SalesInvoice.TotalAmount:sum:InvoiceDate:month)",
        ["NoDashboardTables"] = "comma-separated tables the dashboard leaves out",
        ["AccessMode"] = "Routines or Ef: how search, sort, paging, clone and the junction editors reach the database. Ef uses LINQ over the context and needs no routine in the database; SQLite always uses it; blank = Routines",
        ["ValidatorNamespace"] = "the namespace of the FluentValidation validators CS_Validator writes (default <ProjectName>.App.Validators)",
        ["ApplicationNamespace"] = "the namespace of the commands, queries and handlers CS_CqrsHandlers writes (default <ProjectName>.App.Application)",
        ["ErdTables"] = "comma-separated tables MD_Erd draws (Customer,SalesInvoice); empty: every table",
        ["DtoNamespace"] = "the namespace of the data-transfer classes and mappers (CS_Dto, CS_Mapper, CS_DataContractDto, CS_TypedDataRow, CS_SerializationDtos; default <ProjectName>.App.Dtos)",
        ["FSharpNamespace"] = "the namespace of the F# records FS_Entity and the Rop module FS_Rop write (default <ProjectName>.Domain)",
        ["ReplicationTargets"] = "SQL Server only: linked server and database each change is copied to, comma-separated (server1.Sales,server2.Sales); SP_ReplicationTriggers writes the triggers",
        ["TemporalTables"] = "SQL Server only: comma-separated tables the database versions itself (SP_TemporalTable: SYSTEM_VERSIONING and a <Table>_History table); SP_AuditTable refuses such a table",
        ["KeySequenceTables"] = "SQL Server only: tables whose key comes from the key-sequence table instead of IDENTITY (Customer,Item); their insert routine calls GetNextID",
        ["KeySequenceTable"] = "the table the key sequence is kept in (default AutoInc)",
        ["BulkUpdateColumns"] = "SQL Server only: columns SP_BulkUpdate rewrites in every table that has one (Fnd,Acct)",
        ["BulkUpdateExpression"] = "what those columns are set to, {column} standing for the column (default UPPER({column}))",
        ["NonNegativeColumns"] = "comma-separated money columns that can never be negative (CreditLimit, or Item.Cost for one table): their number box gets a minimum of 0, and the insert, update and save routines refuse a negative value (a CHECK range in the database does the first without the list)",
        ["ApiAnnotations"] = "The plan also writes the DataAnnotations attributes per table (CS_Validation) and the create and update endpoints run them (400 with the messages); works with or without ApiValidation",
        ["DatePairs"] = "comma-separated pairs of date columns where the second must not be earlier than the first (FirstInvoice>LastInvoice, or Project.Opened>Closed for one table): the form refuses an end before its start, the end's date box starts at the start, and the validators say so. The pairs the schema names (a start and end column found by name, or a CHECK of one date against another) are always held to it",
        ["NoDatePairs"] = "comma-separated tables, end columns or Table.End columns that are not held to a start date even though the names or a CHECK constraint say so (Sabbatical, Closed, or Project.Closed)",
        ["NotFutureDateColumns"] = "comma-separated date columns that can never be later than today (BirthDate, or Employee.HireDate for one table): the insert, update and save routines refuse a later date",
        ["EmailColumns"] = "comma-separated text columns that hold an email address whatever their name (Reach, or Contact.Backup for one table): checked, and edited with an email box. A name that is Mail or ends in Mail, or has Email in it, needs no entry",
        ["UrlColumns"] = "comma-separated text columns that hold a web address whatever their name (Where, or Site.Address for one table). A name with Url, Website, Link, Homepage, WebPage or WebAddress in it, or that is Web or ends in Web, needs no entry",
        ["PlainTextColumns"] = "comma-separated text columns whose name says email, phone or URL but that hold something else (EmailTemplate, or Site.PhoneNotes for one table): they get no format check",
        ["ApiFolder"] = "React / Angular folder for the api modules, relative to the source folder; blank = api",
        ["ModelsFolder"] = "React / Angular folder for the TypeScript models; blank = models",
        ["ServicesFolder"] = "Angular folder for the services; blank = services",
        ["ComponentsFolder"] = "React / Angular folder for the shared components and Angular screens; blank = components",
        ["PagesFolder"] = "React folder for the pages; blank = pages",
        ["AngularVersion"] = "major version of Angular, e.g. 22; blank = output that every version from 18 accepts",
        ["ListProtocol"] = "Columns (what API_Search writes: GET <route>/search with a parameter per column) or Search (GET <route>?pageIndex&pageSize&sort=name:desc&search=text, one search box, answered as { data, count }): the generated API, Angular and React all follow it; the API needs essentials --groups crudapi --replace; blank = Columns",
        ["PageParameter"] = "ListProtocol=Search: the query parameter that holds the page; blank = pageIndex (pageNumber with PageBase 1)",
        ["PageSizeParameter"] = "ListProtocol=Search: the query parameter that holds the page size; blank = pageSize",
        ["SortParameter"] = "ListProtocol=Search: the query parameter that holds the sort (column:asc or column:desc); blank = sort",
        ["SearchParameter"] = "ListProtocol=Search: the query parameter that holds the search text; blank = search",
        ["PageBase"] = "ListProtocol=Search: 0 when the first page is 0, 1 when it is 1; blank = 0",
        ["ItemsMember"] = "ListProtocol=Search: the member of the answer that holds the rows of the page; blank = data",
        ["TotalMember"] = "ListProtocol=Search: the member of the answer that holds the number of rows in all; blank = count",
        ["SearchColumns"] = "ListProtocol=Search: Table=Column or Table=Parent.Column pairs, comma-separated (TimeSheet=Notes,TimeSheet=Employee.Name): what the one search box matches; blank = the table's searchable text columns and the display column of its parents",
        ["DefaultSorts"] = "Table=Column:asc|desc pairs, comma-separated (TimeSheet=WhenEntered:desc,Holiday=Name): the sort an Angular grid starts with until the person sorts it",
        ["DockerUpstreamVariable"] = "The Docker group's nginx reads the API's address from this environment variable, and it holds a whole address (https://host:8443), the way .NET Aspire names a service (services__shopapi__https__0); blank = API_UPSTREAM, which holds host:port",
        ["Auth"] = "Angular, React and Blazor: the app signs in. Writes the Auth group (Angular: auth service, token interceptor, route guard, login page; React: api/auth.ts, login page, RequireAuth; Blazor: AuthSession, login page, RedirectToStart; the token lives in sessionStorage), sends the token with every call, guards every generated route, hides the screens ReadRoles does not give the role and the buttons WriteRoles does not give it, and shows the user name with Sign out in the shell. Needs POST api/auth/login answering { token, expiresUtc, user: { name, role } }. Regenerate the project; essentials already written are kept (use --replace for the shell, config, the React Support group and the Blazor Project and Layout groups).",
        ["Toasts"] = "Angular: ngx-toastr shows the API's refusals as toasts (the package is added to package.json and provideToastr to app.config.ts); blank = the browser's alert and confirm dialogs, no package",
        ["MoneyColumns"] = "comma-separated decimal or floating-point columns that hold money whatever their name (Surplus, or Invoice.Surplus for one table): shown as currency. MySQL has no money type, so a decimal(19,4) or decimal(10,4) is currency without an entry unless its name says it counts something",
        ["NotMoneyColumns"] = "comma-separated columns that are not money though their name or size says so (Rate, or Item.Cost for one table): shown as plain numbers",
        ["SingleRowTables"] = "comma-separated tables that hold one row for the whole application (Settings, GeneralLedgerPostingAccount): shown as a form, not a list, on every UI stack",
        ["KeyColumns"] = "the columns that identify a row of a table with no primary key and no unique index (Customer_Memos=Id, or Order_Lines=OrderId+LineNo); comma-separated; every column NOT NULL; without it the unique index, then the identity column, is the key",
        ["IgnoredColumns"] = "comma-separated columns to leave out (Visits, or Place.Location): a type CodeGenNew cannot map, such as PostGIS geometry or a range of timestamps",
        ["ListingName"] = "WinUI3_DirectoryListing: the class stem, e.g. Document (DocumentListPage); blank = Document",
        ["ListingFolder"] = "WinUI3_DirectoryListing: the folder whose files are listed (for example %LocalAppData%/Project/Name); blank = under LocalAppData",
        ["ListingPattern"] = "WinUI3_DirectoryListing: which files are listed; blank = *.*",
        ["Stacks"] = "the stacks Generate All offers ticked for this project; none ticked means you choose them each time",
        ["PlanAlso"] = "templates to run in a whole-project generate although their config leaves them out, e.g. SP_Insert,SP_Update",
        ["OutputApi"] = "folder of the API project under the output folder; blank = <ProjectName>.Api",
        ["OutputWinUI3"] = "folder of the WinUI3 app under the output folder; blank = <ProjectName>.App",
        ["OutputReact"] = "folder of the React app; blank = frontend",
        ["OutputAngular"] = "folder of the Angular app; blank = frontend",
        ["OutputBlazor"] = "folder of the Blazor WebAssembly app; blank = <ProjectName>.Blazor",
        ["OutputUno"] = "folder of the Uno Platform app; blank = <ProjectName>.Uno",
        ["OutputPython"] = "folder of the Python API; blank = <ProjectName>.Python",
        ["OutputRust"] = "folder of the Rust API; blank = <ProjectName>.Rust",
        ["RustCrateName"] = "the crate name of the Rust API; blank = the project name in snake_case",
        ["RustPort"] = "the port the Rust API listens on; blank = ApiPort (5080)",
        ["OutputSql"] = "folder of the generated SQL; blank = <ProjectName>.App/sql",
        ["AppNamespace"] = "root namespace of the WinUI3 app; blank = <ProjectName>.App",
        ["DatabaseProvider"] = "SqlServer, PostgreSql, MySql or Sqlite (appsettings.json and the package reference); blank = SqlServer",
        ["DatabaseServer"] = "server for appsettings.json; blank = localhost",
        ["DatabaseName"] = "database for appsettings.json (for SQLite the path of the database file); blank = the project name",
        ["DatabaseUser"] = "login for appsettings.json (never the password); blank = Windows authentication",
        ["ApiPort"] = "port the API listens on; blank = 5080",
        ["DevPort"] = "port of the front end's dev server; blank = 5173 (React), 4200 (Angular), 5190 (Blazor) or 5195 (the Uno app's browser head)",
        ["ProjectTitle"] = "the web app's title; blank = the project name in words",
        ["BuildApi"] = "command that builds the API after a generate; blank = dotnet build -v q (none skips it)",
        ["BuildWinUI3"] = "command that builds the WinUI3 app after a generate; blank = dotnet build -v q",
        ["BuildReact"] = "command that builds the React app; blank = npm run build",
        ["BuildAngular"] = "command that builds the Angular app; blank = npm run build",
        ["BuildBlazor"] = "command that builds the Blazor app; blank = dotnet build -v q",
        ["BuildUno"] = "command that builds the Uno app; blank = dotnet build -v q -f net10.0-desktop",
        ["BuildPython"] = "command that checks the Python API after a generate; blank = python -m compileall -q app",
        ["BuildRust"] = "command that checks the Rust API after a generate; blank = cargo check (on Windows, a script that sets up the C++ build tools first, then runs cargo)",
        ["TestApi"] = "command that tests the API; blank = no tests",
        ["TestWinUI3"] = "command that tests the WinUI3 app; blank = no tests",
        ["TestReact"] = "command that tests the React app; blank = npm test",
        ["TestAngular"] = "command that tests the Angular app; blank = npm test -- --watch=false",
        ["TestBlazor"] = "command that tests the Blazor app; blank = no tests",
        ["TestUno"] = "command that tests the Uno app; blank = no tests",
        ["TestPython"] = "command that tests the Python API; blank = no tests",
        ["TestRust"] = "command that tests the Rust API; blank = cargo test",
        ["DbSetNames"] = "Plural = Customers, blank = the table name (Customer)",
        ["ProjectName"] = "the project's name (the file name of its .config); every blank namespace and folder is derived from it",
        ["NamingStyle"] = "AsIs (the database's names, the default) or Pascal (customer_item becomes CustomerItem; the SQL keeps the real names)",
        ["Acronyms"] = "comma-separated words the Pascal style keeps upper-case whole (PO,UPC,MSRP)",
        ["Screens"] = "comma-separated tables that get a screen, in menu order; blank = every table that has an API and a search, alphabetically",
        ["NoCloneTables"] = "comma-separated tables that get no Clone button although they could (Customer,SalesInvoice)",
        ["EditableChildren"] = "comma-separated child tables whose rows are added, changed and removed inside the parent's form and saved with it in one request: the child (ProjectTask), or Parent.Child (Department.DepartmentTeam) for a child that also points at another table. The child needs an identity whole-number key and one NOT NULL link to the parent; Angular and React (the master-detail page); blank = every child grid is read-only. Refresh the CrudApi group with --replace",
        ["SeedTables"] = "comma-separated tables whose current rows are written as seed data, a parent before its children (Region,Currency): a class per table that adds its rows when the table is empty and the class that runs them all. The rows are read when you generate, so load them first; an identity key is numbered again from 1. Blank = nothing is seeded",
        ["ChildGridTitles"] = "Parent.Child=Title pairs, comma-separated, for a child grid whose table name does not say what the rows mean (Customer.CustomerItem=Item Purchase History)"
    };
}
